import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router';
// import api from '../api/api';

const SearchResult = () => {
  const [properties, setProperties] = useState([]);
  const [searchParams] = useSearchParams();
  console.log("searchParams")


  useEffect(() => {
    console.log('Inside fetchProperties')
    const fetchProperties = async () => {
      try {
        console.log('inside fetchProperties')
        const query = searchParams.toString();
        const response = await fetch(`http://localhost:8080/search?{searchParams}`,{
          method :'GET',
          headers:{
            'Content-Type':'application/json'
          }
        })
        console.log(await response.json());
       
        // const response = await api.get(`/properties?${query}`);
        setProperties(await response.body);
      //   setProperties([{
      //     type: 'house',
      //     price: '121212',
      //     phone: '121',
      //     email: 'abc1',
      //     description: 'desc1',
      //     location: 'ind',
      //     googleLocation: 'g1'
        
      //   },
      //   {
      //     type: 'flate',
      //     price: '3345',
      //     phone: '121',
      //     email: 'abc2',
      //     description: 'd2',
      //     location: 'indore',
      //     googleLocation: 'g2'
      //   }
      // ]);
        console.log( properties);
        
      } catch (error) {
        console.error('Error fetching properties:', error);
      }
    };
     fetchProperties();
  }, [searchParams]);

  return (
    <div>

    <h3>{searchParams.get("location")}</h3>
    <h3>{searchParams.get("priceMin")}</h3>
    <h3>{searchParams.get("priceMax")}</h3>
    <h3>{searchParams.get("size")}</h3>
    <h3>{searchParams.get("type")}</h3>
    <h3>{searchParams.get("rentOrSell")}</h3>


      {properties.length ? (
        properties.map((property) => (
          <div key={property._id}>
            <h3>{property.type}</h3>
            <p>{property.location}</p>
            <p>{property.description}</p>
            <p>{property.price}</p>
            <p>{property.email}</p>
            <p>{property.phone}</p>
            ||
            {/* <img src={`http://localhost:5000/${property.images[0]}`} alt={property.type} style={{ width: '100px', height: '100px' }} /> */}
          </div>
          
        ))
      ) : (
        <p>No properties found</p>
      )}
    </div>
  );
};

export default SearchResult;
